nextflow_process {

    name "Test Process FFQ"
    script "../main.nf"
    process "FFQ"

    tag "modules"
    tag "modules_nfcore"
    tag "ffq"

    test("test-ffq-single-id") {

        when {
            process {
                """
                input[0] = [ 'SRR9990627' ]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.json).match() },
                { assert snapshot(process.out.versions_ffq).match("test-ffq-single-id_versions") }
            )
        }
    }

    test("test-ffq-multiple-ids") {

        when {
            process {
                """
                input[0] = [ 'SRR9990627', 'SRX7347523' ]

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.json).match() },
                { assert snapshot(process.out.versions_ffq).match("test-ffq-multiple-ids_versions") }
            )
        }
    }

}

